import{_ as t,o as s,c as o,a2 as d}from"./chunks/framework.C8822HRV.js";const u=JSON.parse('{"title":"Skill pack","description":"Where the product-agnostic sdd skill pack lives, how a product supplies its own names and commands, and which procedures the shipped roles follow.","frontmatter":{"title":"Skill pack","description":"Where the product-agnostic sdd skill pack lives, how a product supplies its own names and commands, and which procedures the shipped roles follow.","head":[["meta",{"property":"og:title","content":"Skill pack · sdd"}],["meta",{"property":"og:description","content":"Where the product-agnostic sdd skill pack lives, how a product supplies its own names and commands, and which procedures the shipped roles follow."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/guides/skills/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Skill pack · sdd"}],["meta",{"name":"twitter:description","content":"Where the product-agnostic sdd skill pack lives, how a product supplies its own names and commands, and which procedures the shipped roles follow."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/guides/skills/"}]]},"headers":[],"relativePath":"guides/skills.md","filePath":"guides/skills.md","lastUpdated":1794141620000}'),a={name:"guides/skills.md"};function i(r,e,n,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="skill-pack" tabindex="-1">Skill pack <a class="header-anchor" href="#skill-pack" aria-label="Permalink to &quot;Skill pack&quot;">​</a></h1><p>The skill pack is a set of procedures an agent can follow when a change needs more than the short role file. The role files stay the routing contract. The pack does not replace them.</p><p>The recorded validation in <code>skills/sdd-design-writer/VALIDATION.md</code> used CLI <strong>0.24.0</strong> on Node.js <strong>v24.22.2</strong>. That run advanced the design examples with <code>sdd next</code> on a feature change. This page did not re-run it. The record is that runtime, not coverage of Node 20 or of every later Node release.</p><h2 id="where-it-lives" tabindex="-1">Where it lives <a class="header-anchor" href="#where-it-lives" aria-label="Permalink to &quot;Where it lives&quot;">​</a></h2><p>The files are under <code>skills/</code> at the repository root. Each procedure is <code>skills/&lt;name&gt;/SKILL.md</code>.</p><p>That directory is the home for three reasons:</p><ul><li><strong>Init stays the same.</strong> <code>packages/core/defaults/</code> is what <code>sdd init</code> copies into a product. The pack is optional, so it is not in defaults and init does not write <code>.sdd/skill-config.yaml</code>.</li><li><strong>Host install stays the same.</strong> <code>sdd agents install</code> still writes thin agents only. It does not copy this pack into a host skill folder.</li><li><strong>The site stays the map.</strong> A <code>SKILL.md</code> has its own front matter and is what an agent loads. This page is the human index. The skill text is not published as a second copy.</li></ul><p>Start at <code>skills/README.md</code>. The npm package does not include that directory. Use a checkout of this repository, or copy the <code>skills/</code> folder next to the agent that should load it.</p><h2 id="what-a-product-fills-in" tabindex="-1">What a product fills in <a class="header-anchor" href="#what-a-product-fills-in" aria-label="Permalink to &quot;What a product fills in&quot;">​</a></h2><p>Names, extra bans, tools, component lists, and commands stay in the product repository, in <code>.sdd/skill-config.yaml</code>. The empty example is <code>skills/product-config.example.yaml</code>. Leave a key empty when you do not know it. The skill asks. The only assumed default is <code>authority: human</code>, which means the person, the same approver the shipped role files already use.</p><h2 id="procedures" tabindex="-1">Procedures <a class="header-anchor" href="#procedures" aria-label="Permalink to &quot;Procedures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Procedure</th><th>Use it when</th></tr></thead><tbody><tr><td><code>sdd-design-writer</code></td><td>The stage is design, architecture, hld, or lld. The note must include contracts, edge cases, races, risks with mitigations, out of scope, and acceptance.</td></tr><tr><td><code>sdd-acceptance-gate</code></td><td>Implementation is done and someone must compare evidence to those acceptance rows. It does not sign.</td></tr><tr><td><code>sdd-smallest-change</code></td><td>The implement stage should change only what the accepted design requires.</td></tr><tr><td><code>sdd-ux-writer</code></td><td>A person will see the change. States and copy only.</td></tr><tr><td><code>sdd-ui-binder</code></td><td>Those states should be bound to components the product already listed.</td></tr><tr><td><code>sdd-qa-writer</code></td><td>Someone needs scenarios and the evidence to attach. The person records the result.</td></tr><tr><td><code>sdd-constitution-interview</code></td><td>The constitution is still a skeleton, or the person named one section to revise.</td></tr><tr><td><code>sdd-default-roles</code></td><td>You need to know which procedure the shipped planner, architect, builder, or software-team role follows.</td></tr></tbody></table><p><code>sdd-default-roles</code> does not rewrite <code>.sdd/roles</code>. Planner, architect, and builder are still written by <code>sdd setup</code> when that folder is empty. Their <code>never</code> lists still hold: the planner and architect do not write product code, and the builder does not generate a release.</p><h2 id="design-writer" tabindex="-1">Design writer <a class="header-anchor" href="#design-writer" aria-label="Permalink to &quot;Design writer&quot;">​</a></h2><p>The bundled template remains approach, components, data flow, alternatives, and risks. The design writer keeps that material and requires the longer note. <code>sdd next</code> still only checks that the file is substantive. The pack&#39;s checker checks the headings and the tables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills/sdd-design-writer/scripts/check-design.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/design.md</span></span></code></pre></div><p>Two hypothetical notes are checked in:</p><ul><li><code>skills/sdd-design-writer/examples/inventory-stock-reservation/design.md</code></li><li><code>skills/sdd-design-writer/examples/offline-notes-sync/design.md</code></li></ul><p>They are fiction. Do not copy one into a product and treat it as that product&#39;s design. The skeleton at <code>skills/sdd-design-writer/assets/design.md</code> fails the checker on purpose. Copy that skeleton over <code>.sdd/templates/design.md</code> only when the product wants new changes to start from it, and never over a template the product has already edited.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./roles">Roles and duties</a></li><li><a href="./simple-feature">Simple feature</a></li><li><a href="./../reference/layout">Folders</a></li></ul>',21)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
